package org.jlinalg.cli;

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import static org.jlinalg.cli.NextflowFiles.*;

/** Original exact-edition CrossMap conversion and complete captured result inspection. */
final class CrossmapToolsCli {
    private CrossmapToolsCli() { }
    static int run(String[] args,PrintStream output,PrintStream error){
        Path created=null;
        try{
            if(args.length==0||args.length==1&&args[0].equals("--help")){emit(output,help());return output.checkError()?2:0;}
            if(args.length==1&&args[0].equals("--profiles")){
                emit(output,NextflowJson.json(Map.of("original_editions",List.of("0.5.2","0.6.3"),"selected_formats",List.of("bed","vcf","bigwig"),"execution_provider","Linux x86_64 CPython3.12.3 with separately installed pinned dependencies","author_Python37_reproduced",false,"source_or_author_editions_inferred",false,"source_programs_rewritten",false)));return output.checkError()?2:0;
            }
            if(args.length==2&&args[0].equals("--export-runtime-setup")){export(Path.of(args[1]));emit(output,"Separate CrossMap runtime setup exported; no installation or user conversion performed. Read README.txt.\n"+CrossmapWorkflow.ACTION);return output.checkError()?2:0;}
            if(args.length==2&&args[0].equals("--verify")){CrossmapBundle.verify(Path.of(args[1]),false,()->{});emit(output,"Complete captured original CrossMap result verified. Every selected record and native binary/reference contract was checked; no producer runtime or source model was rerun.\n"+CrossmapWorkflow.ACTION);return output.checkError()?2:0;}
            var options=new LinkedHashMap<String,String>();for(int i=0;i<args.length;i+=2)if(i+1>=args.length||!Set.of("--request","--home","--setup-report","--out","--inspect-runtime").contains(args[i])||options.putIfAbsent(args[i],args[i+1])!=null)throw new IOException("Require complete unique CrossMap options; see --help");
            if(options.containsKey("--inspect-runtime")){
                if(!options.keySet().equals(Set.of("--inspect-runtime","--setup-report")))throw new IOException("Use --inspect-runtime HOME --setup-report COMPLETED_SETUP_REPORT");var runtime=new CrossmapRuntime(Path.of(options.get("--inspect-runtime")),Path.of(options.get("--setup-report")));emit(output,NextflowJson.json(runtime.provenance())+"\nRuntime/source integrity checked; no user conversion admitted.");return output.checkError()?2:0;
            }
            if(!options.keySet().containsAll(Set.of("--request","--out")))throw new IOException("Require an explicit typed --request and NEW --out; see --help");
            if(!options.containsKey("--home")||!options.containsKey("--setup-report"))throw new CrossmapRuntime.Unavailable("Exact private runtime home and completed matching setup report are required; dependent analysis skipped");
            created=CrossmapWorkflow.start(Path.of(options.get("--request")),Path.of(options.get("--home")),Path.of(options.get("--setup-report")),Path.of(options.get("--out")));emit(output,"Original exact-edition CrossMap conversion and complete source-output contracts completed: "+created+"\n"+CrossmapWorkflow.ACTION);emit(error,"WARNINGS AND REQUIRED ACTION: read "+created.resolve("WARNINGS.md")+" and every ledger/source diagnostic before downstream use.");if(output.checkError()||error.checkError()){var failure=new IOException("Result-report output stream failed");CrossmapWorkflow.failure(created,"REPORT_RESULT_TO_CALLER",failure);return 2;}return 0;
        }catch(Exception|LinkageError failure){int code=failure instanceof CrossmapRuntime.Unavailable?3:2;emit(error,(code==3?"SKIP3 DEPENDENT ANALYSIS SKIPPED: ":"FAIL2 NO COMPLETE RESULT: ")+failure+"\n"+CrossmapWorkflow.ACTION);return error.checkError()?2:code;}
    }
    private static void export(Path supplied)throws IOException {
        Path root=supplied.toAbsolutePath().normalize();if(root.getParent()==null||!root.getParent().toRealPath().equals(root.getParent()))throw new IOException("Require canonical existing setup-export parent");Files.createDirectory(root);
        try{var files=new TreeMap<String,Object>();for(String name:List.of("source-lock.json","setup.py","health.py")){byte[] data=CrossmapRuntime.resource(name);Files.write(root.resolve(name),data,StandardOpenOption.CREATE_NEW);files.put(name,CrossmapRuntime.bytesPin(data));}String text="CROSSMAP PRIVATE RUNTIME SETUP ONLY\n\nThis export did not install software or run a user conversion.\nRequire Linux x86_64 CPython3.12.3, including Linux Python inside WSL.\nFrom this exported directory, use absolute NEW private home/report paths:\n\npython3 -B setup.py --home /absolute/NEW_HOME --report /absolute/NEW_REPORT --cache /absolute/WHEEL_CACHE --allow-install --allow-download\n\nFor offline setup, provide all exact locked wheels in WHEEL_CACHE and omit --allow-download. Recheck an existing complete home with a NEW report and no install/download flags. Require COMPLETED.json, WARNINGS.md and all6original artificial format controls. Recheck does not reseal modified files.\n\nThe profile contains original0.5.2 and0.6.3, NumPy1.26.4,pysam0.22.1,bx-python0.12.0,pyBigWig0.3.24,Cython3.0.12. The selected provider is not P072's reported Python3.7 environment. Original sources/licenses remain unmodified; installation is private and separate from analysis.\n\nSKIP3: required permitted platform/interpreter/install/download/access is unavailable; dependent conversion skipped. Supply the named exact permitted prerequisite or retain the skip. FAIL2: changed/incomplete source/runtime, invalid data or process/capacity failure; preserve all attempts and use new paths after correction. Never refresh old seals. Setup health is synthetic and admits no user analysis or whole-paper reproduction.\n";Files.writeString(root.resolve("README.txt"),text,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);files.put("README.txt",pin(root.resolve("README.txt"),65536,()->{}));writeJson(root.resolve("export.json"),Map.of("schema_version",1,"status","EXPORTED_RUNTIME_SETUP_NOT_RUN","user_analysis_admitted",false,"files",files));}
        catch(IOException|RuntimeException failure){try{Files.writeString(root.resolve("FAILURE.txt"),"CrossMap setup export failed. No user conversion admitted. Retain this directory; correct the named cause and export to a new path.\n"+failure+"\n",StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);}catch(IOException detail){failure.addSuppressed(detail);}throw failure;}
    }
    private static String help(){return "crossmap-tools --profiles\n--export-runtime-setup NEW_DIRECTORY\n--inspect-runtime PRIVATE_HOME --setup-report COMPLETED_SETUP_REPORT\n--request TYPED_REQUEST.json --home PRIVATE_HOME --setup-report COMPLETED_SETUP_REPORT --out NEW_CONVERSION\n--verify COMPLETE_CAPTURED_CONVERSION\n\nExact original0.5.2/0.6.3 BED,VCF and BigWig coordinate conversion. Original programs perform mapping and allele/signal handling; Java checks complete captured bytes, record witnesses, reference bases and native raw BigWig intervals. No version or unreported author setting is inferred. Analysis requires Linux Java; complete portable verification works on Windows and Linux using the exact producing JAR. No analysis-time download/install, genome retrieval, generic-mapper fallback, phasing, imputation or GWAS model.\n\nRead docs/literature/CROSSMAP_WORKFLOWS.md for the explicit request fields, source-version limitations, warnings and required actions.\n\n"+CrossmapWorkflow.ACTION;}
    private static void emit(PrintStream stream,String text){stream.writeBytes((text+"\n").getBytes(StandardCharsets.UTF_8));}
}
